/**
 * OpenAI Node - Version 1.5
 * Discriminator: resource=image, operation=analyze
 */


interface Credentials {
  openAiApi: CredentialReference;
}

/** Take in images and answer questions about them */
export type LcOpenAiV15ImageAnalyzeParams = {
  resource: 'image';
  operation: 'analyze';
/**
 * Model
 * @builderHint Keep a working or explicitly requested model unless provider evidence shows it is unavailable or unsuitable. When choosing a new model, select a current stable model supported by this node version, the configured API, and the required operation. Use the declared model-list lookup with the connected credential when available. Gateway credits can restrict that list. For a new choice without credentials, use current provider catalog information. Choose a model that fits the task and budget. Copy the exact model ID. Do not rely on node defaults, invent model IDs, or treat an unfamiliar model as invalid.
 * @searchListMethod imageModelSearch
 * @default {"mode":"list","value":""}
 */
    modelId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Text Input
 * @default What's in this image?
 */
    text?: string | Expression<string>;
/**
 * Input Type
 * @default url
 */
    inputType?: 'url' | 'base64' | Expression<string>;
/**
 * URL(s) of the image(s) to analyze, multiple URLs can be added separated by comma
 * @displayOptions.show { inputType: ["url"] }
 */
    imageUrls?: string | Expression<string>;
/**
 * Name of the binary property which contains the image(s)
 * @hint The name of the input field containing the binary file data to be processed
 * @displayOptions.show { inputType: ["base64"] }
 * @default data
 */
    binaryPropertyName?: string | Expression<string>;
/**
 * Whether to simplify the response or not
 * @default true
 */
    simplify?: boolean | Expression<boolean>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Detail
     * @default auto
     */
    detail?: 'auto' | 'low' | 'high' | Expression<string>;
    /** Fewer tokens will result in shorter, less detailed image description
     * @default 300
     */
    maxTokens?: number | Expression<number>;
  };
};

export interface LcOpenAiV15ImageAnalyzeSubnodeConfig {
  tools?: ToolInstance[];
  memory?: MemoryInstance;
}

export type LcOpenAiV15ImageAnalyzeNode = {
  type: '@n8n/n8n-nodes-langchain.openAi';
  version: 1.5;
  isTrigger: true;
  config: NodeConfig<LcOpenAiV15ImageAnalyzeParams> & { credentials?: Credentials } & { subnodes?: LcOpenAiV15ImageAnalyzeSubnodeConfig };
};